def column_totals(rows):
    if not rows:
        return []
    result = []
    for i in range(len(rows[0])):
        total = 0
        has_numeric = False
        for row in rows:
            if i < len(row):
                val = row[i]
                if isinstance(val, (int, float)):
                    total += val
                    has_numeric = True
        if has_numeric:
            result.append(total)
        else:
            result.append("")
    return result

